<div class="vr-module"><div class="vr-module-head"><div><h1>İletişim mesajları</h1><p>Site iletişim formlarından gelen talepler.</p></div><strong><?= (int)$newCount ?> yeni mesaj</strong></div><div class="vr-module-card"><?php foreach($messages as $msg): ?><article class="vr-message <?= e($msg['status']) ?>"><div class="vr-message-head"><div><strong><?= e($msg['name']) ?></strong> · <a href="mailto:<?= e($msg['email']) ?>"><?= e($msg['email']) ?></a><?php if($msg['phone']): ?> · <?= e($msg['phone']) ?><?php endif; ?><div><small><?= e($msg['created_at']) ?><?= $msg['subject']?' · '.e($msg['subject']):'' ?></small></div></div><form method="post" action="<?= e(app_url('/admin/messages/status')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$msg['id'] ?>"><select name="status"><?php foreach(['new'=>'Yeni','read'=>'Okundu','replied'=>'Yanıtlandı','archived'=>'Arşivlendi'] as $k=>$v): ?><option value="<?= e($k) ?>" <?= $msg['status']===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><button type="submit">Durumu kaydet</button></form></div><p><?= e($msg['message']) ?></p></article><?php endforeach; ?><?php if(!$messages): ?><p>Henüz mesaj yok.</p><?php endif; ?></div></div>